<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { api, ApiError, money } from './api';
import { type Data, dateLabel, stateLabel, modeLabel, randomKey } from './commerce';
import type { Menu } from './types';
import './commerce.css';
import './manager-polish.css';
import { ClipboardList, Users, Gift, Ticket, Settings2, Store, SlidersHorizontal, Bike, BarChart3, History, Trophy, CheckCircle2, RefreshCw, Plus, Minus, ArrowRight, Wallet, Coins } from 'lucide-vue-next';
const props=defineProps<{menu:Menu;role:string}>();
const base=`commerce/manage/${props.menu.store.id}`;
const tab=ref('orders'),busy=ref(false),error=ref(''),notice=ref(''),orders=ref<Data[]>([]),members=ref<Data[]>([]),resources=ref<Data[]>([]),redemptions=ref<Data[]>([]),audit=ref<Data[]>([]),stats=ref<Data|null>(null);
const policy=ref<Data|null>(null),options=ref<Data>({}),detail=ref<Data|null>(null),filter=ref(''),query=ref(''),riders=ref<Data[]>([]);
const form=ref<Data|null>(null),formId=ref<number|null>(null),kind=ref('coupons'),ledgerRows=ref<Data[]|null>(null),adjustment=ref<Data|null>(null);
type AssetRequest={member_id:number;payload:{kind:string;delta:number;reason:string;request_key:string}};
const pendingAdjustment=ref<AssetRequest|null>(null);
const assetFrozen=computed(()=>busy.value||!!pendingAdjustment.value);
const identity=ref<Data|null>(null),identityDirty=ref(false),memberEdit=ref<Data|null>(null);
const selectedDish=ref(0),optionGroups=ref<Data[]>([]),optionsDirty=ref(false),policyDirty=ref(false);
const canManage=computed(()=>['SUPER_ADMIN','STORE_ADMIN'].includes(props.role));
const dishes=computed(()=>props.menu.categories.flatMap(c=>c.dishes));
const tabs=computed(()=>canManage.value?[['orders','订单处理'],['members','会员与资产'],['policy','营业设置'],['identity','门店资料'],['options','规格加料'],['coupons','优惠券'],['rewards','积分商城'],['tasks','成长任务'],['riders','配送员'],['redemptions','兑换核销'],['stats','经营统计'],['audit','操作记录']]:(props.role==='ORDER_OPERATOR'?[['orders','订单处理'],['redemptions','兑换核销']]:[['orders','订单处理']]));
const icons:Record<string,any>={orders:ClipboardList,members:Users,policy:Settings2,identity:Store,options:SlidersHorizontal,coupons:Ticket,rewards:Gift,tasks:Trophy,riders:Bike,redemptions:CheckCircle2,stats:BarChart3,audit:History};
const descriptions:Record<string,string>={orders:'从接单到完成，每一步清晰可查。',members:'查找会员，管理积分与储值，随时追溯每笔变动。',policy:'设置营业时间、取餐方式与会员成长规则。',identity:'维护顾客看到的门店信息。',options:'配置份量、口味和加料，让顾客按需选择。',coupons:'管理优惠券和生日礼遇。',rewards:'管理积分奖品与可兑换库存。',tasks:'设置成长目标与积分奖励。',riders:'维护本店配送员与联系方式。',redemptions:'核对兑换码，完成交付或退回积分。',stats:'查看本店与双店的订单表现及未收款金额。',audit:'追溯操作人、处理时间与变更原因。'};
const navigation=computed(()=>[{title:'日常经营',keys:['orders','members','redemptions']},{title:'会员营销',keys:['coupons','rewards','tasks']},{title:'门店设置',keys:['policy','identity','options','riders']},{title:'数据记录',keys:['stats','audit']}].map(g=>({...g,items:tabs.value.filter(t=>g.keys.includes(t[0]))})).filter(g=>g.items.length));
function mobileTab(event:Event){const el=event.target as HTMLSelectElement;const previous=tab.value;changeTab(el.value).then(()=>{if(tab.value===previous)el.value=previous;});}
const assetDelta=computed(()=>{const a=adjustment.value;if(!a)return 0;const raw=String(a.amount).trim();const valid=a.kind==='WALLET'?/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(raw):/^[1-9]\d*$/.test(raw);if(!valid)return 0;const amount=a.kind==='WALLET'?Math.round(Number(raw)*100):Number(raw);return Number.isSafeInteger(amount)&&amount>0&&amount<=1000000?amount*(a.direction==='decrease'?-1:1):0;});
const assetAfter=computed(()=>adjustment.value?adjustment.value.balance+assetDelta.value:0);
const canAdjust=computed(()=>!!adjustment.value&&adjustment.value.enabled&&adjustment.value.balanceFresh&&assetDelta.value!==0&&assetAfter.value>=0&&adjustment.value.reason.trim().length>=3);
const assetText=(value:number,kind:string)=>kind==='WALLET'?'¥'+money(value):value.toLocaleString('zh-CN')+' 积分';
watch(()=>adjustment.value&&JSON.stringify([adjustment.value.member_id,adjustment.value.kind,assetDelta.value,adjustment.value.reason.trim()]),()=>{if(adjustment.value&&!pendingAdjustment.value)adjustment.value.request_key=randomKey();},{flush:'sync'});
async function call<T=Data>(path:string,method='GET',data?:unknown):Promise<T>{return api<T>(`${base}/${path}`,{method,...(data===undefined?{}:{body:JSON.stringify(data)})});}
async function run(fn:()=>Promise<void>,silent=false){if(busy.value)return;busy.value=true;if(!silent){error.value='';notice.value='';}try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function confirmLeave(){if(pendingAdjustment.value){error.value='资产调整结果尚未确认，请先重试确认结果后再离开。';return false;}return !(optionsDirty.value||policyDirty.value||identityDirty.value||memberEdit.value||form.value||adjustment.value)||confirm('有尚未保存的内容，确定离开？');}
async function refresh(){if(confirmLeave())await run(load);}
defineExpose({confirmLeave,reload:()=>run(load)});
async function load(){
 if(tab.value==='orders'){orders.value=await call<Data[]>(`orders?status=${encodeURIComponent(filter.value)}&q=${encodeURIComponent(query.value)}`);riders.value=await call<Data[]>('resources/riders');}
 else if(tab.value==='members')members.value=await call<Data[]>(`members?q=${encodeURIComponent(query.value)}`);
 else if(tab.value==='identity'){identity.value=await call('identity');identityDirty.value=false;}
 else if(tab.value==='policy'){policy.value=await call('policy');policyDirty.value=false;}
 else if(tab.value==='options'){options.value=await call('options');if(!selectedDish.value)selectedDish.value=dishes.value[0]?.id||0;selectDish();}
 else if(tab.value==='stats'){stats.value=await call('stats');if(props.role==='SUPER_ADMIN')stats.value!.overview=await api<Data>('commerce/overview');}
 else if(tab.value==='redemptions')redemptions.value=await call<Data[]>('redemptions');
 else if(tab.value==='audit')audit.value=await call<Data[]>('audit');
 else {kind.value=tab.value;resources.value=await call<Data[]>(`resources/${kind.value}`);}
}
async function changeTab(t:string){if(!confirmLeave())return;optionsDirty.value=false;policyDirty.value=false;form.value=null;adjustment.value=null;memberEdit.value=null;identityDirty.value=false;query.value='';tab.value=t;await run(load);}
function nextStates(o:Data){const states:Record<string,string[]>={PENDING:['ACCEPTED','CANCELLED'],ACCEPTED:['PREPARING','CANCELLED'],PREPARING:['READY','CANCELLED'],READY:[o.fulfillment==='delivery'?'DELIVERING':'COMPLETED','CANCELLED'],DELIVERING:['COMPLETED','CANCELLED']};return (states[o.status]||[]).filter(s=>canManage.value||props.role==='ORDER_OPERATOR'||(props.role==='KITCHEN_OPERATOR'&&['PREPARING','READY'].includes(s))||(props.role==='DELIVERY_OPERATOR'&&o.fulfillment==='delivery'&&['DELIVERING','COMPLETED'].includes(s)));}
const riderId=ref<number|null>(null),cancelReason=ref('');
function openOrder(o:Data){detail.value=o;riderId.value=o.rider_id||null;cancelReason.value='';}
async function transition(state:string){if(!detail.value)return;if(state==='CANCELLED'&&!cancelReason.value.trim()){error.value='请先填写取消原因';return;}await run(async()=>{detail.value=await call(`orders/${detail.value!.number}/state`,'POST',{status:state,expected_status:detail.value!.status,reason:state==='CANCELLED'?cancelReason.value:'',rider_id:riderId.value});await load();notice.value='订单状态已更新';});}
async function more(){await run(async()=>{if(tab.value==='orders'&&orders.value.length){const rows=await call<Data[]>(`orders?status=${encodeURIComponent(filter.value)}&q=${encodeURIComponent(query.value)}&before=${orders.value.at(-1)!.id}`);orders.value.push(...rows);if(!rows.length)notice.value='已加载全部订单';}else if(tab.value==='members'&&members.value.length){members.value.push(...await call<Data[]>(`members?q=${encodeURIComponent(query.value)}&before=${members.value.at(-1)!.id}`));}});}
const localDate=(s:string)=>{const d=new Date(s);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
function openForm(row?:Data){formId.value=row?.id||null;const start=new Date(),end=new Date(Date.now()+30*86400000);const defaults:Record<string,Data>={coupons:{title:'',amount_cents:500,minimum_cents:2000,quantity:100,starts_at:localDate(start.toISOString()),expires_at:localDate(end.toISOString()),birthday_only:false,enabled:true},rewards:{title:'',description:'',points_cost:100,stock:10,enabled:true},tasks:{title:'',kind:'ORDER_COUNT',target:1,points_reward:10,enabled:true},riders:{name:'',phone:'',enabled:true}};form.value=row?Object.fromEntries(Object.keys(defaults[kind.value]).map(k=>[k,k.endsWith('_at')?localDate(row[k]):row[k]])):defaults[kind.value];}
async function saveResource(){await run(async()=>{const data={...form.value};if(kind.value==='coupons'){data.starts_at=new Date(data.starts_at).toISOString();data.expires_at=new Date(data.expires_at).toISOString();}await call(`resources/${kind.value}${formId.value?'/'+formId.value:''}`,formId.value?'PUT':'POST',data);form.value=null;await load();notice.value='已保存';});}
async function saveIdentity(){await run(async()=>{identity.value=await call('identity','PUT',identity.value);identityDirty.value=false;notice.value='门店资料已保存，重新载入页面后显示新资料';});}
async function saveMember(){await run(async()=>{const {id,...data}=memberEdit.value!;await call(`members/${id}/profile`,'PUT',{...data,birthday:data.birthday||null});memberEdit.value=null;await load();notice.value='会员资料已更正';});}
async function savePolicy(){await run(async()=>{policy.value=await call('policy','PUT',policy.value);policyDirty.value=false;notice.value='营业设置已保存';});}
function changeDish(event:Event){const select=event.target as HTMLSelectElement;if(optionsDirty.value&&!confirm('规格尚未保存，确定切换菜品？')){select.value=String(selectedDish.value);return;}selectedDish.value=Number(select.value);selectDish();}
function selectDish(){optionGroups.value=JSON.parse(JSON.stringify(options.value[String(selectedDish.value)]||[]));optionsDirty.value=false;}
function addGroup(){optionGroups.value.push({id:'g_'+randomKey().slice(0,8),name:'',minimum:0,maximum:1,options:[{id:'o_'+randomKey().slice(0,8),name:'',price_cents:0,enabled:true}]});optionsDirty.value=true;}
async function saveOptions(){await run(async()=>{const r=await call(`options/${selectedDish.value}`,'PUT',{groups:optionGroups.value});options.value[String(selectedDish.value)]=r.groups;optionsDirty.value=false;notice.value='规格已保存，顾客刷新菜单后生效';});}
async function toggleMember(m:Data){if(!confirm(`${m.enabled?'停用':'启用'}此会员账号？`))return;await run(async()=>{await call(`members/${m.id}/enabled`,'PATCH',{enabled:!m.enabled});await load();});}
async function viewLedger(m:Data){await run(async()=>{ledgerRows.value=await call<Data[]>(`members/${m.id}/ledgers`);});}
async function openAdjustment(m:Data,kind='POINTS'){if(pendingAdjustment.value){confirmLeave();return;}await run(async()=>{const rows=await call<Data[]>(`members?q=${encodeURIComponent(m.phone)}`);const current=rows.find(row=>row.id===m.id);if(!current||!current.enabled)throw new Error('会员状态已变化，请刷新后重试');adjustment.value={member_id:m.id,name:current.name||'未填写姓名',phone:current.phone,kind,balance:kind==='POINTS'?current.points:current.wallet_cents,enabled:current.enabled,balanceFresh:true,direction:'increase',amount:'',reason:'',request_key:randomKey()};});}
function closeAdjustment(){if(!assetFrozen.value)adjustment.value=null;}
async function refreshAdjustment(a:Data){
 const rows=await call<Data[]>(`members?q=${encodeURIComponent(a.phone)}`);
 const current=rows.find(row=>row.id===a.member_id);
 a.enabled=!!current?.enabled;
 if(!current)return;
 a.balance=a.kind==='POINTS'?current.points:current.wallet_cents;
 a.balanceFresh=true;
 members.value=members.value.map(row=>row.id===current.id?current:row);
}
async function adjust(){
 if(!pendingAdjustment.value&&!canAdjust.value)return;
 await run(async()=>{
  const a=adjustment.value;if(!a)return;
  const request=pendingAdjustment.value??{member_id:a.member_id,payload:{kind:a.kind,delta:assetDelta.value,reason:a.reason.trim(),request_key:a.request_key}};
  pendingAdjustment.value=request;
  let row:Data;
  try{row=await call(`members/${request.member_id}/adjust`,'POST',request.payload);}
  catch(e){
   if(e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==408){
    pendingAdjustment.value=null;a.request_key=randomKey();a.balanceFresh=false;
    error.value=e.message;
    try{await refreshAdjustment(a);}catch{error.value+=' 余额暂时无法刷新，请关闭后重新打开调整窗口。';}
   }else error.value='本次调整结果尚未确认，请点击“重试确认结果”。确认前不能修改内容或重新发起调整。';
   return;
  }
  pendingAdjustment.value=null;adjustment.value=null;
  notice.value=`已${row.delta>0?'增加':'减少'}${assetText(Math.abs(row.delta),row.kind)}，本次变动后${row.kind==='WALLET'?'储值余额':'积分'} ${assetText(row.balance,row.kind)}`;
  await load();
 });
}
async function redemption(r:Data,status:string){if(!confirm(status==='REDEEMED'?'确认已核对兑换码并完成核销？':'取消兑换并返还积分？'))return;await run(async()=>{await call(`redemptions/${r.id}/state`,'POST',{status});await load();});}
function printOrder(){window.print();}
function beforeUnload(e:BeforeUnloadEvent){if(optionsDirty.value||policyDirty.value||identityDirty.value||memberEdit.value||form.value||adjustment.value){e.preventDefault();e.returnValue='';}}
let timer:ReturnType<typeof setInterval>;
onMounted(()=>{run(load);window.addEventListener('beforeunload',beforeUnload);timer=setInterval(()=>{if(tab.value==='orders'&&!busy.value&&!detail.value&&!document.hidden)run(load,true);},20000);});
onBeforeUnmount(()=>{clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template>
 <section class="cx-manager">
 <div class="cm-environment"><span class="cm-status-dot"></span><strong>在线支付未开通</strong><span>订单金额未收款</span></div>
 <div class="cm-workspace"><aside class="cm-sidebar"><div class="cm-store"><Store :size="21"/><div><strong>{{menu.store.name}}</strong><small>门店业务管理</small></div></div><nav aria-label="经营工作台导航"><div v-for="group in navigation" :key="group.title" class="cm-nav-group"><span>{{group.title}}</span><button v-for="t in group.items" :key="t[0]" :class="{active:tab===t[0]}" :aria-current="tab===t[0]?'page':undefined" :disabled="busy" @click="changeTab(t[0])"><component :is="icons[t[0]]" :size="18"/>{{t[1]}}</button></div></nav></aside>
 <div class="cm-main"><label class="cm-mobile-nav">功能导航<select :value="tab" :disabled="busy" @change="mobileTab"><optgroup v-for="group in navigation" :label="group.title"><option v-for="t in group.items" :value="t[0]">{{t[1]}}</option></optgroup></select></label>
 <header class="cm-section-heading"><div><span class="cm-section-eyebrow">门店工作台</span><h2>{{tabs.find(t=>t[0]===tab)?.[1]}}</h2><p>{{descriptions[tab]}}</p></div><button class="cx-secondary cm-refresh" :disabled="busy" @click="refresh"><RefreshCw :size="16" :class="{spinning:busy}"/>{{busy?'处理中':'刷新'}}</button></header>
 <p v-if="error" class="cx-error" role="alert">{{error}}</p><p v-if="notice" class="cm-success" role="status"><CheckCircle2 :size="18"/>{{notice}}</p>
 <template v-if="tab==='orders'"><div class="cx-row wrap"><select v-model="filter" class="cx-input" aria-label="订单状态" @change="run(load)"><option value="">全部状态</option><option v-for="s in ['PENDING','ACCEPTED','PREPARING','READY','DELIVERING','COMPLETED','CANCELLED']" :value="s">{{stateLabel(s)}}</option></select><input v-model="query" class="cx-input" placeholder="搜索订单号" @keyup.enter="run(load)"></div><div class="cx-table-wrap"><table class="cx-table"><thead><tr><th>订单</th><th>顾客 / 取餐方式</th><th>商品</th><th>订单金额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.number}}<br><small>{{dateLabel(o.created_at)}}</small></td><td>{{o.contact}}<br>{{modeLabel(o.fulfillment)}} {{o.table_number}}</td><td>{{o.items.map((i:Data)=>`${i.name}×${i.quantity}`).join('，')}}</td><td>¥{{money(o.total_cents)}}<br><small>未支付</small></td><td><span class="cx-tag">{{stateLabel(o.status)}}</span></td><td><button class="cx-secondary" @click="openOrder(o)">查看 / 处理</button></td></tr></tbody></table></div><p v-if="!orders.length" class="cx-empty">暂无符合条件的订单。</p><button v-if="orders.length>=50" class="cx-secondary" @click="more">加载更多</button></template>
 <template v-if="tab==='members'"><form class="cm-search" @submit.prevent="run(load)"><label class="cx-sr-only" for="cm-member-search">会员手机号</label><input id="cm-member-search" v-model="query" class="cx-input" placeholder="输入会员手机号"><button class="cx-primary" :disabled="busy">查找会员</button><span>{{members.length}} 位已加载</span></form><div class="cm-member-grid"><article v-for="m in members" :key="m.id" class="cm-member-card"><header><div class="cm-avatar">{{(m.name||'会').slice(0,1)}}</div><div class="cx-grow"><strong>{{m.name||'未填写姓名'}}</strong><small>{{m.phone}}</small></div><span class="cx-tag">{{m.enabled?m.level:'已停用'}}</span></header><div class="cm-member-assets"><div><span>积分</span><strong>{{m.points.toLocaleString('zh-CN')}}</strong><button class="cm-asset-action" :disabled="busy||!m.enabled" @click="openAdjustment(m,'POINTS')"><Coins :size="15"/>调积分</button></div><div><span>储值余额（元）</span><strong>¥{{money(m.wallet_cents)}}</strong><button class="cm-asset-action" :disabled="busy||!m.enabled" @click="openAdjustment(m,'WALLET')"><Wallet :size="15"/>调储值</button></div></div><footer><span>累计完成订单金额 ¥{{money(m.lifetime_cents)}}</span><div><button class="cm-text-button" @click="viewLedger(m)">资产流水</button><button class="cm-text-button" @click="memberEdit={id:m.id,name:m.name,birthday:m.birthday,reason:''}">资料</button><button class="cm-text-button cm-muted-action" @click="toggleMember(m)">{{m.enabled?'停用':'启用'}}</button></div></footer></article></div><p v-if="!members.length" class="cx-empty">暂无符合条件的本店会员。</p><button v-if="members.length>=50" class="cx-secondary" @click="more">加载更多</button></template>
 <form v-if="tab==='identity'&&identity" class="cx-card" @submit.prevent="saveIdentity" @input="identityDirty=true"><label class="cx-field"><span>门店名称</span><input v-model="identity.name" required maxlength="100"></label><label class="cx-field"><span>门店联系电话</span><input v-model="identity.phone" required maxlength="30"></label><p class="cx-help">门店地址、配送坐标和配送范围在“配送设置”维护。</p><button class="cx-primary" :disabled="busy">保存门店资料</button></form>
 <form v-if="tab==='policy'&&policy" @submit.prevent="savePolicy" @input="policyDirty=true" @change="policyDirty=true"><div class="cx-card"><h3>接单与费用</h3><label><input v-model="policy.accepting_orders" type="checkbox"> 接受订单</label><label class="cx-field"><span>门店公告</span><input v-model="policy.announcement" maxlength="300"></label><div class="cx-options"><label v-for="mode in ['pickup','dine_in','delivery']"><input v-model="policy.fulfillments" type="checkbox" :value="mode"> {{modeLabel(mode)}}</label></div><div class="cx-grid"><label class="cx-field"><span>外送最低起送金额（分）</span><input v-model.number="policy.minimum_delivery_cents" type="number" min="0" max="1000000" required></label><label class="cx-field"><span>每件包装费（分，堂食免收）</span><input v-model.number="policy.packaging_per_item_cents" type="number" min="0" max="10000" required></label></div><p class="cx-help">100 分 = 1 元。配送坐标、常送地点及配送费在上方“配送设置”维护。</p></div><div class="cx-card"><h3>营业时段（北京时间）</h3><p class="cx-help">未添加时段表示全天。跨午夜请拆为两段；结束可填24:00。</p><div v-for="(h,i) in policy.hours" class="cx-row wrap"><label class="cx-field"><span>星期</span><select v-model.number="h.day"><option v-for="(d,n) in ['一','二','三','四','五','六','日']" :value="n">星期{{d}}</option></select></label><label class="cx-field"><span>开始</span><input v-model="h.start" type="time" required></label><label class="cx-field"><span>结束</span><input v-model="h.end" type="text" placeholder="21:00 或 24:00" pattern="([01][0-9]|2[0-3]):[0-5][0-9]|24:00" required></label><button type="button" class="cx-danger" @click="policy.hours.splice(i,1);policyDirty=true">移除</button></div><button type="button" class="cx-secondary" @click="policy.hours.push({day:0,start:'09:00',end:'21:00'});policyDirty=true">添加营业时段</button></div><div class="cx-card"><h3>会员成长</h3><label class="cx-field"><span>每完成1元订单赠送积分</span><input v-model.number="policy.points_per_yuan" type="number" min="0" max="100" required></label><div v-for="(t,i) in policy.tiers" class="cx-row wrap"><label class="cx-field"><span>等级名称</span><input v-model="t.name" required maxlength="30"></label><label class="cx-field"><span>累计完成订单金额门槛（分）</span><input v-model.number="t.threshold_cents" type="number" min="0" required></label><button v-if="i" type="button" class="cx-danger" @click="policy.tiers.splice(i,1);policyDirty=true">移除</button></div><button type="button" class="cx-secondary" @click="policy.tiers.push({name:'新等级',threshold_cents:policy.tiers.at(-1).threshold_cents+100000});policyDirty=true">添加等级</button></div><button class="cx-primary" :disabled="busy">保存营业设置</button></form>
 <template v-if="tab==='options'"><label class="cx-field"><span>选择菜品</span><select :value="selectedDish" @change="changeDish"><option v-for="d in dishes" :value="d.id">{{d.name}}</option></select></label><p class="cx-help">例如“份量”最少1项、最多1项；“加料”最少0项、最多3项。删除全部规格可恢复普通菜品。</p><form @submit.prevent="saveOptions" @input="optionsDirty=true" @change="optionsDirty=true"><div v-for="(g,i) in optionGroups" :key="g.id" class="cx-card"><div class="cx-row"><label class="cx-field cx-grow"><span>规格组名称</span><input v-model="g.name" required maxlength="60"></label><button type="button" class="cx-danger" @click="optionGroups.splice(i,1);optionsDirty=true">删除此组</button></div><div class="cx-grid"><label class="cx-field"><span>最少选择</span><input v-model.number="g.minimum" type="number" min="0" max="10" required></label><label class="cx-field"><span>最多选择</span><input v-model.number="g.maximum" type="number" min="1" max="10" required></label></div><div v-for="(o,n) in g.options" :key="o.id" class="cx-row wrap"><label class="cx-field"><span>选项名称</span><input v-model="o.name" required maxlength="60"></label><label class="cx-field"><span>加价（分）</span><input v-model.number="o.price_cents" type="number" min="0" max="100000" required></label><label><input v-model="o.enabled" type="checkbox"> 可选</label><button type="button" class="cx-danger" @click="g.options.splice(n,1);optionsDirty=true">移除</button></div><button type="button" class="cx-secondary" @click="g.options.push({id:'o_'+randomKey().slice(0,8),name:'',price_cents:0,enabled:true});optionsDirty=true">添加选项</button></div><div class="cx-actions"><button type="button" class="cx-secondary" @click="addGroup">添加规格组</button><button class="cx-primary" :disabled="busy||!selectedDish">保存菜品规格</button></div></form></template>
 <template v-if="['coupons','rewards','tasks','riders'].includes(tab)"><button class="cx-primary" @click="openForm()">新增{{tabs.find(t=>t[0]===tab)?.[1]}}</button><div class="cx-table-wrap"><table class="cx-table"><thead><tr><th>名称</th><th>规则 / 联系方式</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in resources" :key="r.id"><td>{{r.title||r.name}}</td><td><template v-if="tab==='coupons'">满 ¥{{money(r.minimum_cents)}} 减 ¥{{money(r.amount_cents)}} · 总量 {{r.quantity}}<br>{{dateLabel(r.expires_at)}} 到期 {{r.birthday_only?'· 生日券':''}}</template><template v-if="tab==='rewards'">{{r.points_cost}} 积分 · 库存 {{r.stock}}</template><template v-if="tab==='tasks'">{{r.kind==='PROFILE'?'完善资料':r.kind==='SPEND'?'累计订单金额':'完成订单'}} · 目标 {{r.target}} · 奖励 {{r.points_reward}} 积分</template><template v-if="tab==='riders'">{{r.phone}}</template></td><td>{{r.enabled?'启用':'停用'}}</td><td><button class="cx-secondary" @click="openForm(r)">编辑</button></td></tr></tbody></table></div><p v-if="!resources.length" class="cx-empty">还没有记录，可新增经营规则。</p></template>
 <template v-if="tab==='redemptions'"><div class="cx-table-wrap"><table class="cx-table"><thead><tr><th>兑换码</th><th>奖品 / 会员编号</th><th>积分</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in redemptions" :key="r.id"><td><strong>{{r.code}}</strong><br><small>{{dateLabel(r.created_at)}}</small></td><td>{{r.title}}<br>#{{r.member_id}}</td><td>{{r.points_cost}}</td><td>{{r.status==='PENDING'?'待核销':stateLabel(r.status)}}</td><td v-if="r.status==='PENDING'"><button class="cx-primary" :disabled="busy" @click="redemption(r,'REDEEMED')">核销</button><button class="cx-danger" :disabled="busy" @click="redemption(r,'CANCELLED')">取消并退积分</button></td></tr></tbody></table></div><p v-if="!redemptions.length" class="cx-empty">暂无兑换记录。</p></template>
 <template v-if="tab==='stats'&&stats"><section v-if="stats.overview" class="cx-card"><h3>跨门店汇总</h3><div v-for="store in stats.overview.stores" class="cx-card"><h4>{{store.name}} · {{store.members}} 位会员</h4><p v-for="s in store.by_status">{{stateLabel(s.status)}}：{{s.count}} 单 · 未支付 ¥{{money(s.unpaid_total_cents)}}</p><p v-if="!store.by_status.length">暂无订单</p></div></section><p class="cx-note">最近 {{stats.days}} 天的订单。在线支付尚未开通；下方金额均未收款，不作为营业收入。</p><div class="cx-stat-grid"><div class="cx-card"><h3>本店会员</h3><strong class="cx-balance">{{stats.members}}</strong></div><div v-for="s in stats.by_status" class="cx-card"><h3>{{stateLabel(s.status)}}</h3><strong class="cx-balance">{{s.count}} 单</strong><p>未收款金额 ¥{{money(s.unpaid_total_cents)}}</p></div></div></template>
 <template v-if="tab==='audit'"><div v-for="a in audit" :key="a.id" class="cx-card"><div class="cx-row"><strong>{{a.action}}</strong><small>{{dateLabel(a.created_at)}}</small></div><p>{{a.actor}} · {{a.subject}}</p><p v-if="a.detail.reason">{{a.detail.reason}}</p><small v-if="a.detail.status">{{stateLabel(a.detail.status)}}</small></div><p v-if="!audit.length" class="cx-empty">暂无操作记录。</p></template>
 <div v-if="detail" class="cx-overlay" @click.self="detail=null"><section class="cx-dialog cx-print" role="dialog" aria-modal="true" aria-label="订单处理"><div class="cx-dialog-header"><h2>{{stateLabel(detail.status)}}</h2><button class="cx-secondary" @click="detail=null">关闭</button></div><p class="cx-note">订单未支付 · 尚未收款</p><strong>{{detail.number}}</strong><p>{{detail.contact}} · {{detail.phone}}</p><p>{{modeLabel(detail.fulfillment)}} {{detail.table_number}}</p><p v-if="detail.address">{{detail.address.title}} {{detail.address.detail}}</p><p v-if="detail.note">备注：{{detail.note}}</p><div v-for="i in detail.items" class="cx-card"><div class="cx-row"><strong>{{i.name}} ×{{i.quantity}}</strong><span>¥{{money(i.total_cents)}}</span></div><small>{{i.options.map((x:Data)=>x.option).join(' / ')}}</small></div><p>包装费 ¥{{money(detail.packaging_cents)}} · 配送费 ¥{{money(detail.delivery_cents)}} · 优惠 ¥{{money(detail.discount_cents)}}</p><h3>合计 ¥{{money(detail.total_cents)}}</h3><div v-for="e in detail.events" class="cx-event"><strong>{{stateLabel(e.status)}}</strong><p>{{dateLabel(e.at)}} · {{e.reason}}</p></div><label v-if="nextStates(detail).includes('DELIVERING')" class="cx-field"><span>分配配送员</span><select v-model="riderId"><option :value="null">请选择</option><option v-for="r in riders.filter(r=>r.enabled)" :value="r.id">{{r.name}} · {{r.phone}}</option></select></label><label v-if="nextStates(detail).includes('CANCELLED')" class="cx-field"><span>取消原因（仅取消时必填）</span><input v-model="cancelReason" maxlength="200"></label><p v-if="error" class="cx-error">{{error}}</p><div class="cx-actions"><button v-for="s in nextStates(detail)" :class="s==='CANCELLED'?'cx-danger':'cx-primary'" :disabled="busy" @click="transition(s)">{{s==='CANCELLED'?'取消订单':s==='ACCEPTED'?'确认接单':s==='PREPARING'?'开始制作':s==='READY'?'制作完成':s==='DELIVERING'?'开始配送':'确认完成'}}</button><button class="cx-secondary" @click="printOrder">打印小票</button></div></section></div>
 <div v-if="form" class="cx-overlay" @click.self="form=null"><form class="cx-dialog" role="dialog" aria-modal="true" aria-label="编辑经营规则" @submit.prevent="saveResource"><div class="cx-dialog-header"><h2>{{formId?'编辑':'新增'}}{{tabs.find(t=>t[0]===kind)?.[1]}}</h2><button type="button" class="cx-secondary" @click="form=null">关闭</button></div><label class="cx-field"><span>名称</span><input v-if="kind==='riders'" v-model="form.name" required maxlength="60"><input v-else v-model="form.title" required maxlength="100"></label><label v-if="kind==='riders'" class="cx-field"><span>手机号</span><input v-model="form.phone" type="tel" pattern="1[3-9][0-9]{9}" required></label><template v-if="kind==='coupons'"><div class="cx-grid"><label class="cx-field"><span>优惠金额（分）</span><input v-model.number="form.amount_cents" type="number" min="1" required></label><label class="cx-field"><span>最低商品金额（分）</span><input v-model.number="form.minimum_cents" type="number" min="0" required></label><label class="cx-field"><span>发放总量（每位会员限领一张）</span><input v-model.number="form.quantity" type="number" min="1" required></label></div><label class="cx-field"><span>开始时间</span><input v-model="form.starts_at" type="datetime-local" required></label><label class="cx-field"><span>结束时间</span><input v-model="form.expires_at" type="datetime-local" required></label><label><input v-model="form.birthday_only" type="checkbox"> 仅生日当月可领取</label><p class="cx-help">已领取优惠券保留领取时的规则；修改仅影响后续领取。</p></template><template v-if="kind==='rewards'"><label class="cx-field"><span>奖品说明</span><textarea v-model="form.description" maxlength="500"></textarea></label><div class="cx-grid"><label class="cx-field"><span>所需积分</span><input v-model.number="form.points_cost" type="number" min="1" required></label><label class="cx-field"><span>可兑换库存</span><input v-model.number="form.stock" type="number" min="0" required></label></div></template><template v-if="kind==='tasks'"><label class="cx-field"><span>任务类型</span><select v-model="form.kind"><option value="PROFILE">完善姓名和生日</option><option value="ORDER_COUNT">累计完成订单数</option><option value="SPEND">累计完成订单金额（分）</option></select></label><div class="cx-grid"><label class="cx-field"><span>目标（资料任务填1）</span><input v-model.number="form.target" type="number" min="1" required></label><label class="cx-field"><span>奖励积分</span><input v-model.number="form.points_reward" type="number" min="1" required></label></div><p class="cx-help">每位会员对同一任务只能领取一次。</p></template><label class="cx-field"><input v-model="form.enabled" type="checkbox" style="width:auto"> 启用</label><p v-if="error" class="cx-error">{{error}}</p><button class="cx-primary" :disabled="busy">保存</button></form></div>
 <div v-if="adjustment" class="cx-overlay"><form class="cx-dialog cm-asset-dialog" role="dialog" aria-modal="true" aria-label="调整会员资产" @submit.prevent="adjust"><div class="cx-dialog-header"><div><span class="cm-section-eyebrow">{{menu.store.name}}</span><h2>{{adjustment.kind==='POINTS'?'调整积分':'调整储值'}}</h2></div><button type="button" class="cx-secondary" :disabled="assetFrozen" @click="closeAdjustment">关闭</button></div><div class="cm-member-identity"><div class="cm-avatar">{{adjustment.name.slice(0,1)}}</div><div><strong>{{adjustment.name}}</strong><small>{{adjustment.phone}}</small></div><span class="cx-tag">会员资产</span></div>
 <fieldset class="cm-direction"><legend>调整方式</legend><label :class="{selected:adjustment.direction==='increase'}"><input v-model="adjustment.direction" type="radio" value="increase" :disabled="assetFrozen"><Plus :size="18"/>增加</label><label :class="{selected:adjustment.direction==='decrease',decrease:true}"><input v-model="adjustment.direction" type="radio" value="decrease" :disabled="assetFrozen"><Minus :size="18"/>减少</label></fieldset>
 <label class="cx-field"><span>{{adjustment.kind==='WALLET'?'调整金额（元）':'调整数量（积分）'}}</span><input v-model="adjustment.amount" :disabled="assetFrozen" type="text" :inputmode="adjustment.kind==='WALLET'?'decimal':'numeric'" :placeholder="adjustment.kind==='WALLET'?'例如 50.00':'例如 100'" required autocomplete="off" maxlength="12"></label><p class="cx-help">{{adjustment.kind==='WALLET'?'填写正数金额，最多两位小数，单次最多10,000元。':'填写正整数，单次最多1,000,000积分。'}}</p>
 <div class="cm-balance-preview"><div><small>当前{{adjustment.kind==='WALLET'?'储值':'积分'}}</small><strong>{{assetText(adjustment.balance,adjustment.kind)}}</strong></div><ArrowRight :size="22"/><div :class="{invalid:assetAfter<0}"><small>调整后预计</small><strong>{{assetText(assetAfter,adjustment.kind)}}</strong></div></div><p v-if="assetAfter<0" class="cx-error" role="alert">减少数量超过当前余额，请重新填写。</p><p v-else-if="adjustment.amount&&!assetDelta" class="cx-error" role="alert">请输入符合要求的正数。</p>
 <label class="cx-field"><span>调整原因</span><textarea v-model="adjustment.reason" :disabled="assetFrozen" required minlength="3" maxlength="200" rows="2" placeholder="例如：活动赠送、录入纠错或人工扣减"></textarea></label><p class="cx-help">每笔人工调整均保留流水及操作记录，请核对会员、金额与调整原因。</p><p v-if="!adjustment.enabled" class="cx-error" role="alert">会员已停用或不存在，无法调整资产。</p><p v-if="error" class="cx-error" role="alert">{{error}}</p><button class="cx-primary cm-submit" :disabled="busy||(!pendingAdjustment&&!canAdjust)">{{busy?'正在确认…':pendingAdjustment?'重试确认结果':`确认${adjustment.direction==='increase'?'增加':'减少'}${adjustment.kind==='WALLET'?'储值':'积分'}`}}</button></form></div>
 <div v-if="memberEdit" class="cx-overlay"><form class="cx-dialog" role="dialog" aria-modal="true" aria-label="更正会员资料" @submit.prevent="saveMember"><div class="cx-dialog-header"><h2>更正会员资料</h2><button type="button" class="cx-secondary" @click="memberEdit=null">关闭</button></div><label class="cx-field"><span>姓名 / 昵称</span><input v-model="memberEdit.name" required maxlength="60"></label><label class="cx-field"><span>生日</span><input v-model="memberEdit.birthday" type="date"></label><label class="cx-field"><span>更正原因</span><input v-model="memberEdit.reason" required minlength="3" maxlength="200"></label><p v-if="error" class="cx-error">{{error}}</p><button class="cx-primary" :disabled="busy">保存会员资料</button></form></div>
 <div v-if="ledgerRows" class="cx-overlay" @click.self="ledgerRows=null"><section class="cx-dialog" role="dialog" aria-modal="true" aria-label="会员资产流水"><div class="cx-dialog-header"><h2>会员资产流水</h2><button class="cx-secondary" @click="ledgerRows=null">关闭</button></div><div v-for="l in ledgerRows" class="cx-card"><div class="cx-row"><strong>{{l.kind==='POINTS'?'积分':'余额'}}</strong><span>{{l.delta>0?'+':'−'}}{{l.kind==='POINTS'?Math.abs(l.delta):'¥'+money(Math.abs(l.delta))}}</span></div><p>{{l.reason}}</p><small>{{dateLabel(l.created_at)}} · 变动后 {{assetText(l.balance,l.kind)}}</small></div><p v-if="!ledgerRows.length" class="cx-empty">暂无流水。</p></section></div>
 </div></div></section>
</template>
